import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.ClientBoundDataDrivenUIReload{}
EMPTY = bytes.fromhex("")

GOLDENS = [
    pytest.param(v.ClientboundDataDrivenUIReloadPacket(), EMPTY, id=f"{v.__name__.rpartition('.')[2]}-empty")
    for v in VERSIONS
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_data_driven_ui_reload_is_packet_335(version):
    assert version.PACKETS[335] is version.ClientboundDataDrivenUIReloadPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_data_driven_ui_reload_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_data_driven_ui_reload_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_data_driven_ui_reload_rejects_trailing_bytes(version):
    with pytest.raises(ValueError, match="trailing bytes"):
        version.ClientboundDataDrivenUIReloadPacket.from_bytes(bytes.fromhex("ff7f01"))
